import{c as t,Q as o,j as r,m as a}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"Terms of Use","description":"","frontmatter":{"title":"Terms of Use"},"headers":[],"relativePath":"en/terms.md","filePath":"en/terms.md","lastUpdated":1794895051000}'),i={name:"en/terms.md"};function n(s,e,l,c,u,d){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="fmcl-terms-of-use" tabindex="-1">FMCL Terms of Use <a class="header-anchor" href="#fmcl-terms-of-use" aria-label="Permalink to &quot;FMCL Terms of Use&quot;">​</a></h1><blockquote><p>This English translation is provided for convenience only. If there is any discrepancy between this translation and the authoritative Chinese text at <a href="/terms">FMCL 用户协议</a>, the Chinese version prevails.</p></blockquote><p><strong>Version: 1.3.1</strong><strong>Effective date: 2026-08-14</strong></p><p>Thank you for using FMCL (Fusion Minecraft Launcher, hereinafter &quot;the Software&quot;). The Software is developed by the FMCL Team (hereinafter &quot;the Contributors&quot; or &quot;we&quot;) and released as open source under <strong>GNU General Public License v3.0</strong>.</p><p><strong>Please read this agreement carefully before using the Software.</strong> If you install, copy, download or use the Software in any way, you confirm that you have read and accepted all of its terms. If you do not agree with any part of this agreement, stop using the Software immediately and delete it.</p><h2 id="_1-definitions" tabindex="-1">1. Definitions <a class="header-anchor" href="#_1-definitions" aria-label="Permalink to &quot;1. Definitions&quot;">​</a></h2><ol><li><strong>&quot;The Software&quot;</strong> refers to the FMCL launcher together with its documentation, configuration files, components and updates.</li><li><strong>&quot;Contributors&quot;</strong> refers to every individual or organisation that has contributed code, documentation, translations, issue reports or other resources to the FMCL project.</li><li><strong>&quot;User&quot;</strong> refers to any natural or legal person who installs, configures or runs the Software.</li><li><strong>&quot;Third-party services&quot;</strong> refers to services not provided by the team that the Software may integrate, including but not limited to the Modrinth API, the CurseForge API, BMCLAPI, Jingdu AI, Microsoft account authentication services and EasyTier multiplayer services.</li></ol><h2 id="_2-purpose-and-licensing" tabindex="-1">2. Purpose and licensing <a class="header-anchor" href="#_2-purpose-and-licensing" aria-label="Permalink to &quot;2. Purpose and licensing&quot;">​</a></h2><ol><li>The Software is an open-source Minecraft launching tool that helps users manage, install and launch Minecraft and its mods more conveniently.</li><li>The source code of the Software is licensed under GPL v3.0; you may run, modify and redistribute the Software freely, provided you comply with the GPL.</li><li>This agreement does not replace the GPL. Both take effect independently, and this agreement does not restrict any modification or redistribution of the code that the GPL permits.</li></ol><h2 id="_3-risk-and-disclaimer" tabindex="-1">3. Risk and disclaimer <a class="header-anchor" href="#_3-risk-and-disclaimer" aria-label="Permalink to &quot;3. Risk and disclaimer&quot;">​</a></h2><p><strong>You explicitly understand and agree that:</strong></p><ol><li><strong>You bear the full risk of using the Software.</strong> The Software is provided &quot;AS IS&quot; and &quot;AS AVAILABLE&quot;, without any express or implied warranty, including but not limited to warranties of merchantability, fitness for a particular purpose, non-infringement or uninterrupted operation.</li><li><strong>The Contributors do not guarantee that the Software is free of defects, viruses or errors, or that it fully meets your needs.</strong> We may release updates from time to time but are under no obligation to fix every problem or provide technical support.</li><li><strong>Under no circumstances shall the Contributors be liable for any direct, indirect, incidental, special, punitive or consequential damages arising from the use of, or inability to use, the Software</strong> (including but not limited to data loss, loss of game progress, hardware damage, account bans, device failure, loss of profit or third-party claims), even if the Contributors were advised of the possibility of such damages.</li><li><strong>The Software may call or integrate third-party services</strong> (such as the Modrinth API, the CurseForge API and Jingdu AI). The Contributors are not responsible for the availability, accuracy, security, legality or continuity of these services. When using a third-party service you must also comply with its own terms and privacy policy.</li><li><strong>Some features of the Software (such as P2P multiplayer through EasyTier) may involve network traversal and port forwarding.</strong> You are responsible for ensuring that such behaviour does not violate the laws or regulations of your network or country. The Contributors are not liable for any network failure, security incident or legal issue arising from the use of these features.</li></ol><h2 id="_4-user-conduct" tabindex="-1">4. User conduct <a class="header-anchor" href="#_4-user-conduct" aria-label="Permalink to &quot;4. User conduct&quot;">​</a></h2><p>You agree that, when using the Software, you will not:</p><ol><li>Use the Software for any illegal purpose or in violation of any applicable law, regulation or industry norm.</li><li>Use the Software to spread malicious code, viruses, trojans, worms, backdoors or other harmful programs.</li><li>Reverse engineer, decompile or disassemble the Software, or attempt to obtain its source code, except through the means permitted by this agreement.</li><li>Remove, obscure or modify any copyright notice, licence notice or other notice contained in the Software.</li><li>Use the Software to attack, disrupt or damage any server, network or infrastructure, including but not limited to DDoS attacks, abusive scraping or excessive requests against official Minecraft services, the Modrinth API, the CurseForge API or Jingdu AI services.</li><li>Publish or transmit any insulting, defamatory, obscene, threatening, hateful or otherwise objectionable content through the Software.</li><li>Impersonate others or use the Software under a false identity.</li></ol><p><strong>If you violate the rules above, the Contributors may suspend or terminate your right to use the Software at any time and reserve the right to pursue legal remedies.</strong></p><h2 id="_5-accounts-and-third-party-credentials" tabindex="-1">5. Accounts and third-party credentials <a class="header-anchor" href="#_5-accounts-and-third-party-credentials" aria-label="Permalink to &quot;5. Accounts and third-party credentials&quot;">​</a></h2><ol><li>The Software lets you sign in to a Microsoft account, a Yggdrasil authentication server (such as LittleSkin) and a Jingdu AI account. <strong>You are responsible for keeping all account credentials safe</strong>; the Contributors do not collect, store or process your plaintext passwords.</li><li>The Software stores your access tokens locally, encrypted with AES-128-CBC plus HMAC-SHA256. You should protect the files that hold them (such as <code>config.json</code> and <code>.fmcl_key</code>) against unauthorised access.</li><li>The Contributors are not liable for any loss caused by leaked or misused credentials, or by security problems on the side of third-party providers.</li></ol><h2 id="_6-indemnification" tabindex="-1">6. Indemnification <a class="header-anchor" href="#_6-indemnification" aria-label="Permalink to &quot;6. Indemnification&quot;">​</a></h2><p>You agree to defend, indemnify and hold harmless the Contributors, their affiliates, officers, employees and agents from and against:</p><ul><li>your use of the Software, including the games you launch and the mods, modpacks and server settings you configure;</li><li>your breach of this agreement or of the GPL;</li><li>your infringement of any third-party right, including intellectual property rights, privacy rights or personal rights.</li></ul><h2 id="_7-updates-and-changes-to-this-agreement" tabindex="-1">7. Updates and changes to this agreement <a class="header-anchor" href="#_7-updates-and-changes-to-this-agreement" aria-label="Permalink to &quot;7. Updates and changes to this agreement&quot;">​</a></h2><ol><li>The Contributors may release updates from time to time, including through the automatic updater. Updates may fix defects, add features or remove features. You may accept or decline updates, but some features may only be available in newer versions.</li><li>The Contributors reserve the right to modify this agreement at any time. Before a change takes effect, the updated version is published in the project repository (for example on GitHub) as <code>TERMS_OF_USE.md</code>, and we will make reasonable efforts to notify you through in-app announcements, the README or a startup dialog.</li><li><strong>Continued use of the Software means you accept the amended agreement.</strong> If you do not accept the amendments, stop using the Software immediately and delete it.</li></ol><h2 id="_8-governing-law-and-dispute-resolution" tabindex="-1">8. Governing law and dispute resolution <a class="header-anchor" href="#_8-governing-law-and-dispute-resolution" aria-label="Permalink to &quot;8. Governing law and dispute resolution&quot;">​</a></h2><ol><li>The formation, performance and interpretation of this agreement are governed by the laws of the <strong>People&#39;s Republic of China</strong>, excluding its conflict-of-law rules.</li><li>Any dispute arising from this agreement or from the use of the Software shall first be settled through friendly negotiation. If negotiation fails, either party may bring the dispute before the <strong>competent people&#39;s court in the place where the Contributors&#39; primary servers are located (the People&#39;s Republic of China)</strong>.</li><li>This agreement does not limit any right granted to you by the mandatory consumer protection laws of your country or region.</li></ol><h2 id="_9-miscellaneous" tabindex="-1">9. Miscellaneous <a class="header-anchor" href="#_9-miscellaneous" aria-label="Permalink to &quot;9. Miscellaneous&quot;">​</a></h2><ol><li>If any provision of this agreement is held invalid or unenforceable by a court of competent jurisdiction, the remaining provisions remain in full force.</li><li>This agreement constitutes the entire agreement between you and the Contributors regarding the use of the Software and supersedes any prior oral or written communication, representation or agreement.</li><li>Any right not expressly granted in this agreement is reserved.</li><li>If you find a security vulnerability or illegal content in the Software, please report it anonymously through GitHub Issues or the project&#39;s contact address. We will make reasonable efforts to fix it but are under no obligation to provide any reward or compensation.</li></ol><hr><h2 id="_10-special-notice-minecraft-and-third-party-services" tabindex="-1">10. Special notice: Minecraft and third-party services <a class="header-anchor" href="#_10-special-notice-minecraft-and-third-party-services" aria-label="Permalink to &quot;10. Special notice: Minecraft and third-party services&quot;">​</a></h2><ul><li><strong>Minecraft copyright</strong>: Minecraft and all of its assets belong to Mojang AB. The Software is an independent third-party launcher and is neither endorsed by nor affiliated with Mojang AB.</li><li><strong>Minecraft EULA</strong>: when launching Minecraft with the Software you must still comply with the <a href="https://www.minecraft.net/en-us/eula" target="_blank" rel="noreferrer">Mojang End User Licence Agreement</a>.</li><li><strong>Jingdu AI terms</strong>: if you enable Jingdu AI features, you must also comply with the Jingdu platform&#39;s terms of service and privacy policy.</li><li><strong>Modrinth terms</strong>: mod browsing, downloading and modpack installation use the Modrinth API, and your use is subject to Modrinth&#39;s <a href="https://modrinth.com/legal/terms" target="_blank" rel="noreferrer">Terms of Use</a>.</li><li><strong>CurseForge terms</strong>: browsing, downloading and update checks for mods, modpacks, resource packs and shaders use the <a href="https://docs.curseforge.com/" target="_blank" rel="noreferrer">CurseForge Core API v1</a> at <code>api.curseforge.com</code>. Your use is subject to CurseForge&#39;s <a href="https://www.curseforge.com/legal/terms-of-service" target="_blank" rel="noreferrer">Terms of Service</a> and its API licensing requirements. The Software is not affiliated with CurseForge or its operator.</li><li><strong>CurseForge API key</strong>: CurseForge now requires an API key; without one, CurseForge features are unavailable. The key is supplied through the <code>CURSEFORGE_API_KEY</code> environment variable or embedded at build time. You must apply for your own key at the <a href="https://console.curseforge.com/" target="_blank" rel="noreferrer">CurseForge developer console</a> and comply with its quota, rate limit and key usage rules. An API key is a sensitive credential; do not leak or share it, and you bear the consequences of any leak or misuse.</li><li><strong>CurseForge content copyright</strong>: mods, modpacks, resource packs and shaders on CurseForge remain the property of their respective authors. Downloaded content is for personal lawful use only; it must not be redistributed, resold or used commercially without the author&#39;s permission.</li><li><strong>MCAPPX terms</strong>: the Bedrock Edition version list, installers and data come from the MCAPPX repository. <strong>By using the Software to download or launch Bedrock Edition, you confirm that you have read and accept MCAPPX&#39;s terms of conduct and disclaimer</strong> (<a href="https://www.mcappx.com/terms/" target="_blank" rel="noreferrer">https://www.mcappx.com/terms/</a>).</li><li><strong>Bedrock Edition is not a cracked build</strong>: the Bedrock Edition features of the Software are <strong>not a cracked version</strong>. Bedrock Edition is a commercial game; before using the download and launch features you must hold a lawful Microsoft account and have purchased Minecraft through official channels such as the Microsoft Store or Xbox. <strong>Using the Bedrock Edition features without a purchased account may violate Mojang&#39;s EULA or Microsoft&#39;s terms, and any account ban, property loss or other consequence is borne by you</strong>, not by the Contributors.</li></ul><p><strong>Once again: none of the Contributors accept legal liability for any loss caused by your use or misuse of the Software. If you cannot accept the terms above, delete the Software immediately and stop using it.</strong></p><hr><h2 id="_11-music-player-notice" tabindex="-1">11. Music player notice <a class="header-anchor" href="#_11-music-player-notice" aria-label="Permalink to &quot;11. Music player notice&quot;">​</a></h2><p>The music player borrows design ideas from the open-source project <a href="https://github.com/lyswhut/lx-music-desktop" target="_blank" rel="noreferrer">LX Music</a> and uses a similar approach to obtaining data from third-party music platforms. The following clauses apply specifically to the music player.</p><p><strong>Data sources</strong></p><ol><li>Music search and online playback connect to the public interfaces of third-party platforms (including but not limited to Kuwo, Kugou, Migu, QQ Music and NetEase Cloud Music). The Software merely displays the returned data and <strong>is not responsible for its legality, accuracy or timeliness</strong>.</li><li>The Software does not store, cache or distribute any music files. Online playback obtains a temporary playback link from the third-party platform only when you explicitly press play, and keeps no audio data afterwards.</li><li>The accuracy of search results depends on what the third-party interfaces return; the Software cannot guarantee that results match the platform itself.</li><li><strong>The &quot;original artist&quot; marker on search results is derived by rule matching over metadata returned by the platform (artist, release date, album, cover references and so on); it is not a manually reviewed judgement.</strong> The Contributors are not responsible for the accuracy of platform data and do not guarantee the marker; it is for reference only, and where it differs from the actual original, the platform&#39;s own data and your own verification prevail.</li><li><strong>Automatic cross-source fallback</strong>: when the selected source cannot provide a complete playback link (for example VIP-only or unlicensed tracks) or returns only a preview clip, the Software automatically searches other sources, including Bilibili, by track name, artist and duration and plays the replacement. This matching is based on platform metadata rules and <strong>may match a cover, live version, instrumental or another version; the Software is not responsible for the accuracy of the match</strong>. The copyright of any replacement track belongs to its original rights holder.</li><li><strong>Bilibili risk-control verification</strong>: Bilibili may require a security check (slider CAPTCHA) for anonymous search requests. The Software then shows a prompt and opens your system browser so you can complete the check the platform requires. <strong>The verification process, content and result are entirely controlled by Bilibili</strong>; the temporary credential produced by verification is used only for the current search request, and the Software neither collects nor stores your verification information. If you decline to complete the verification, the fallback feature is unavailable, and nothing else is affected.</li></ol><p><strong>Copyright</strong></p><ol><li>Copyright in music searched and played online through the Software belongs to the original rights holders, including but not limited to record labels, musicians and music platforms.</li><li>The Software owns no copyright in any music data and does not store, copy or distribute it in any form.</li><li><strong>If you want to keep a track after previewing it, purchase it or obtain authorisation through lawful channels.</strong> The Software provides technical exploration and research only; you bear full legal responsibility for any copyright dispute arising from your use of this feature.</li></ol><p><strong>User responsibility</strong></p><ol><li><strong>You bear the full risk of using the online search and playback features.</strong> The Contributors are not liable for any direct, indirect, incidental, special or consequential damage arising from your use of these features.</li><li>You must use the online music features in compliance with local law. If local law prohibits obtaining music through unofficial channels, you must not use these features.</li><li>If playback fails or search results look wrong because a third-party interface changed, broke or was blocked, the Contributors are not obliged to fix it.</li><li><strong>Tracks played through cross-source fallback may come from another platform; their availability and audio quality depend on the providing source and are not guaranteed.</strong> Search on platforms such as Bilibili is rate limited and protected by risk control, so a fallback may legitimately fail.</li></ol><p><strong>Non-commercial nature</strong></p><ol><li>The music player is provided for technical exploration and study only. It accepts no commercial partnership or donation and serves no profit-making purpose.</li><li>The Software is not affiliated with Kuwo, Kugou, Migu, QQ Music, NetEase Cloud Music, Bilibili or any other third-party platform.</li></ol><p><strong>Acceptance</strong></p><p>By using the online music search and playback features you confirm that you have read and fully accept the clauses above. If you do not agree, do not use online music search and playback, or use the local folder playback only.</p><h2 id="_12-plugin-system-notice" tabindex="-1">12. Plugin system notice <a class="header-anchor" href="#_12-plugin-system-notice" aria-label="Permalink to &quot;12. Plugin system notice&quot;">​</a></h2><p>The Software provides a plugin system that lets users install third-party <code>.fmpl</code> plugins to extend the launcher. The following clauses apply specifically to the plugin system.</p><p><strong>Responsibility</strong></p><ol><li><strong>Plugins are developed independently by third parties. Their code, behaviour, security and compliance are entirely the developer&#39;s responsibility.</strong> The Contributors make no express or implied warranty about the content, quality, security or legality of any third-party plugin.</li><li>The Contributors do not review, certify or endorse any third-party plugin. The permissions a plugin requests during installation do not imply this Software&#39;s approval or recommendation.</li><li>The Contributors are not liable for any problem caused by installing, enabling or using a third-party plugin, including but not limited to data loss, game crashes, stolen accounts, system damage, malicious behaviour or legal disputes.</li></ol><p><strong>User responsibility</strong></p><ol><li><strong>Before installing any third-party plugin, review the permission list it requests and the risk level of each permission.</strong> Granting high-risk permissions such as executing external processes, raw socket connections or launch hooks requires careful consideration.</li><li>Obtain <code>.fmpl</code> files from trusted channels. Plugins from unknown sources may contain malicious code.</li><li>You bear the full risk of using plugin features. If you find a plugin with security problems or infringing behaviour, uninstall and delete it immediately.</li></ol><p><strong>Plugin management</strong></p><ol><li>You can enable, disable or uninstall any plugin at any time in Settings → Plugins.</li><li>Granted permissions can be revoked at any time on the plugin management page.</li><li>When a plugin is disabled or uninstalled, the hooks and UI components it registered are removed automatically; the launcher keeps working normally.</li></ol><p><strong>Acceptance</strong></p><p>By installing or enabling any plugin you confirm that you have read and fully accept the clauses above. If you do not agree, do not use the plugin system.</p><p><strong>If you have questions, contact the project maintainers.</strong></p><hr><p><strong>FMCL Team</strong> Project home: <a href="https://github.com/Janson20/FMCL" target="_blank" rel="noreferrer">https://github.com/Janson20/FMCL</a> Contact: open an issue on GitHub</p>',57)])])}const f=t(i,[["render",n]]);export{p as __pageData,f as default};
